import { Resvg } from '@resvg/resvg-js';
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="300" height="160" viewBox="0 0 300 160">
<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f6d8b8"/><stop offset="1" stop-color="#c96f4a"/></linearGradient></defs>
<rect width="300" height="160" fill="url(#g)"/>
<path d="M30 110 C60 60, 120 60, 150 100 C180 60, 240 60, 270 110" fill="none" stroke="#3b2416" stroke-width="6" stroke-linecap="round"/>
<text x="150" y="50" font-family="Georgia" font-size="28" text-anchor="middle" fill="#3b2416">dogear</text>
<text x="150" y="140" font-family="Segoe Print" font-size="18" text-anchor="middle" fill="#fff">one more chapter</text>
</svg>`;
const r = new Resvg(svg, { font: { fontFiles: ['C:\\Windows\\Fonts\\georgia.ttf','C:\\Windows\\Fonts\\segoepr.ttf','C:\\Windows\\Fonts\\comic.ttf','C:\\Windows\\Fonts\\Inkfree.ttf','C:\\Windows\\Fonts\\segoeui.ttf'], loadSystemFonts: false, defaultFontFamily: 'Georgia' } });
const png = r.render().asPng();
const { writeFileSync } = await import('node:fs');
writeFileSync('assets/_smoke.png', png);
console.log('OK bytes=' + png.length);
EOF
